  str_loading_e_h_name111 = "La zona residencial y de gobierno central de la guarnición de Lumopolis, ubicada en Crepúsculo.",
  str_loading_e_h_name112 = "Una cámara cerrada dentro de la prisión de Illumina donde se mantienen a los prisioneros.",
  str_loading_e_h_name113 = "Un reino secreto donde Victoria escucha \"La Verdad.\"",
  str_loading_e_h_name10004 = "Comunidad Acogedora",
  str_loading_e_h_name10005 = "Barrio animado",
  str_loading_e_h_name10006 = "Mundo Exterior Aterrador",
  str_loading_e_h_name10007 = "¿Estás listo, Eve?",
  str_loading_e_h_name20011 = "Donde prevalece la justicia.",
  str_loading_e_h_name20012 = "La cuna de la columna vertebral del futuro de Lumópolis.",
  str_loading_e_h_name20013 = "Un lujoso enclave de nobles.",
  str_loading_e_h_name20014 = "Donde el bullicio y el peligro coexisten.",
  str_loading_e_h_name20015 = "¿Listo para comenzar la siguiente prueba?",
  str_loading_e_h_name80030001 = "La Residencia",
  str_loading_e_h_name80030002 = "Calles conocidas de antes",
  str_loading_e_h_name80030003 = "Un lugar al que regresar",
  str_loading_e_h_name80030004 = "Mundo Acuático",
  str_loading_e_h_name80040001 = "Calle de Comercio Bicontinental",
  str_loading_e_h_name80040002 = "Pequeño Longzhou",
  str_loading_e_h_name80040003 = "Puerto Comercial Bicontinental",
  str_loading_e_h_name80040004 = "Leyenda del espadachín de Twin Pavilions Bay",
  str_loading_e_h_name80050001 = "Epopeya del Héroe Civil",
  str_loading_e_h_name80050002 = "Civilización Milenaria",
  str_loading_e_h_name80050003 = "Fe Milenaria",
  str_loading_e_h_name80050004 = "Rivalidad Milenaria",
  str_loading_desc1 = "Bajo Lumopolis, la tierra de vastas sombras, innumerables personas que viven del comercio y el intercambio de información forman enormes ciudades, mientras que varias fuerzas subterráneas son los gobernantes de facto de estos lugares.",
  str_loading_desc2 = "La región conocida como Astra es la perla en el círculo crepuscular, y para muchos Aurorians, es el único lugar conocido como hogar, donde hay una alternancia regular de día y noche para que la vida florezca.",
  str_loading_desc3 = "Ubicada en el frío norte, la gente puede vivir aquí en paz, gracias al poderoso poder mágico que custodia esta pequeña área. Los asuntos importantes los decide la Reina Bethlehem.",
  str_loading_desc4 = "La última Crisis de Darkover comenzó hace diecisiete años y fue sofocada por una alianza de numerosas facciones. Sin embargo, incluso en comunidades muy unidas existen disputas y animosidad. Especialmente los Aurorians...",
  str_loading_desc5 = "El único hábitat conocido de los Eclipsites. Algunos dicen que tiene algo que ver con los diversos fragmentos que dejó la civilización antigua. Solo podemos especular que podría ser el instinto de Eclipsites el habitar aquí, o podría ser el trabajo de la misteriosa organización, Eclipse...",
  str_loading_desc6 = "Es un abismo donde no brilla la luz, donde la arquitectura es extraña y traicionera, y siempre se puede encontrar la maravilla artesanía de los antiguos. Numerosos aventureros llegaron a este lugar como polillas a la llama por las reliquias y trofeos de una era desconocida, solo para ser enterrados aquí...",
  str_loading_desc7 = "Después de la Crisis de Darkover, que involucró ataques masivos por parte de los Eclipsites hace 17 años, algunos Celestitas lograron escapar de Eraveil. Soroz también tomó un Celestita y lo escondió bajo tierra, aislado del mundo.",
  str_loading_desc8 = "Hace muchos años, cuando los Eclipsites estaban desenfrenados, esta ciudad subterránea de miles de metros de profundidad salvó innumerables vidas. La gente de Ciudad Gannon se organizó de manera eficiente y desarrolló la técnica única de Lumina para construir su sistema de defensa centrado en la Ciudad Gannon.",
  str_loading_desc9 = "Aurorians, Eclipsites, Illumina, Lumopolis... Hay demasiada información en tu cabeza. ¿El reensamblaje de Eclipsites tiene algo que ver con la Crisis de Darkover que ocurrió hace diecisiete años? El viaje en busca de la verdad está destinado a estar lleno de altibajos...",
  str_loading_desc10 = "Una alianza nómada desordenada y franca formada por nómadas vagabundos. Sus miembros huelen a carretera y al viento, vagando por el Desierto de Rediesel, viviendo una vida sin restricciones y sin preocupaciones.",
  str_loading_desc11 = "Supuestamente, la organización planeó la Crisis de Darkover, cuyo verdadero motivo es desconocido para todos. Está compuesta por Eclipsites de alto nivel y ha absorbido a muchos rebeldes de otras razas con un propósito desconocido. El Eclipse desapareció sin dejar rastro después de que las fuerzas de la coalición de ciudades-estado en la región de Astra se ocuparan de la Crisis de Darkover...",
  str_loading_desc12 = "Construida sobre una isla flotante llamada \"Azurite\", esta ciudad es la fortaleza más segura del mundo. Actualmente tiene una jerarquía de poder distintiva, con un triunvirato formado por el Gobernador, el Consejo de Ancianos de los Nobles y los Sacerdotes del Templo. Los nobles de Lumopolis se dedican a mantener el orden actual, mientras que el Templo promueve el culto al sol.",
  str_loading_desc13 = "Una federación no centralizada de un gran número de asentamientos centrados alrededor de una enorme subciudad llamada Gannon, ubicada en la línea del frente de la batalla contra los Eclipsites. La Federación Illumina ha adoptado un sistema de liderazgo colectivo, estableciendo una forma de sociedad completamente diferente a la de Lumopolis.",
  str_loading_desc14 = "Colossus, un legado de la civilización antigua. Tiene tantos secretos que se dice que es imposible analizar su estructura y comprender los principios detrás de él, ni siquiera con todo el conocimiento actual y el esfuerzo de todos los académicos combinados. Muchos de ellos ni siquiera se pueden maniobrar directamente; solo los Celestitas pueden vincularse a la inteligencia del Colossus con su habilidad psíquica para formar un nivel profundo de control y operarlo desde allí.",
  str_loading_desc15 = "El caos causado por la Crisis de Darkover hace 17 años provocó la pérdida de varios objetos misteriosos de Celestitas. Nadie conoce su paradero. Incluso su verdadero propósito se ha ocultado deliberadamente...",
  str_loading_desc16 = "Señor Sombrío, o Istvan, es el más temido en Umbraton. Se dice que su museo personal de colecciones, el Pasillo Susurrante, contiene una gran cantidad de horribles coleccionables. Si tienes la suerte de sobrevivir a los peligros ocultos detrás de los ladrillos y telarañas, puedes encontrar cosas interesantes...",
  str_loading_desc17 = "Los residentes de Umbraton parecen tener dos lados: sonrientes y fríos, amables y crueles. Esta es también una característica de Umbraton. Mientras te adaptes a él, este lugar es el paraíso, y si no, será el infierno.",
  str_loading_desc18 = "En el continente de Astra, se han revelado rastros de innúmeras reliquias de la antigüedad, y la Cumbre recién descubierta es una de ellos. Lo que asombra a la gente no es solo su altura, sino también su asombroso poder y las leyendas sobre los tesoros escondidos en su interior...",
  str_loading_desc19 = "Los que obtienen su poder de la Luz y luchan con ella, son los principales habitantes del continente. Aparte de ellos, pocos grupos pueden enfrentarse a los Eclipsites.",
  str_loading_desc20 = "Criaturas de origen desconocido. Han sido los enemigos mortales de todas las comunidades desde el comienzo de la historia registrada. Salvo los Aurorians, casi nadie puede luchar contra ellos.",
  str_loading_desc21 = "Material para hacer una señal de ayuda. Se puede utilizar para reclutar Aurorians para que se unan a la aventura. Desafortunadamente, no hay garantía sobre quién responderá a tal señal.",
  str_loading_desc22 = "Parece un piano y los comandos se ingresan tocando en este panel de control de Colossus. Solo los Celestitas pueden entender bien su idioma.",
  str_loading_desc23 = "Las barreras naturales y numerosos Colossus aseguraron la paz aquí durante cientos de años.\nAl igual que las tecnologías Colossus, el origen de los Celestitas está envuelto en un misterio y es imposible de verificar.\nSi esta paz puede durar para siempre, este lugar volverá a florecer como antes.",
  str_loading_desc24 = "El tiempo no ha curado las cicatrices de hace diecisiete años. Lo que sucedió ese día vive en la vívida realidad del presente.\nDesde ese día, nadie ha vuelto a este lugar... hasta hoy.",
  str_loading_desc25 = "Ese día coincidió con un gran festival y la gente no estaba preparada.\nLa caída de Eraveil parece haber sido inevitable, y Schummer fue simplemente un catalizador necesario.",
  str_loading_desc26 = "Aviduz fue una vez una unidad especial entre los muchos Colossus de Eraveil. De enorme tamaño e incomparable en función, poseía un potencial ilimitado.\nDebido a esto, las demandas impuestas a su Navegador también fueron particularmente estrictas.",
  str_loading_desc27 = "En el centro de Aviduz hay una cápsula de curación que brinda tratamiento de emergencia a los heridos graves.\nBajo la providencia de una fuerza misteriosa, Schummer recuperó un poder mucho mayor de lo que nadie esperaba.",
  str_loading_desc28 = "Un área oscura ubicada al borde de Eternal Night. Aquí, los días son cortos y las noches son largas, y todo el lugar rebosa de Darkflow.\nSolía haber muchos asentamientos aurorianos aquí, pero todos han sido abandonados desde hace bastante tiempo. Las ruinas en ruinas continúan desmoronándose, y la bulliciosa vivacidad del pasado yace cubierta de polvo.\nHoy en día, todo lo que queda son tierras baldías, ruinas y enjambres de Eclipsitas, y ningún Auroriano cuerdo está dispuesto a volver a poner un pie aquí debido al persistente Darkflow...",
  str_loading_desc29 = "Entrañas ubicada en el borde de la Noche Eterna que una vez sirvió como punto de apoyo de la Federación Illumina contra los Eclipsites.\nSin embargo, después de una invasión de Eclipsite hace mucho tiempo, fue abandonado.\nSe dice que quedaron muchos suministros y tecnologías de cuando los soldados de Illumina se retiraron, pero pocos están dispuestos a desafiar el denso flujo oscuro y enfrentarse al ejército de Eclipsite para recuperarlos.",
  str_loading_desc30 = "No hay muchos que conozcan este antiguo túnel de escape, pero es un milagro que todavía exista hasta el día de hoy.\nPuede que sea el único camino a la superficie, así que es mejor seguirlo.\nDerrota a todos los enemigos que encuentres en este antiguo pasadizo lleno de balas. Puede que simplemente escapes y, quién sabe, puede que te lleve a la batalla final.",
  str_loading_h_desc1 = "Este es el desierto de Rediesel del sur de Astra, donde un mar de arena dorada se extiende hasta donde alcanza la vista.\nBajo la mirada del sol abrasador, esta tierra estéril y asolada por la sequía es uno de los lugares más inhabitables de Astra.\nSolo las formas de vida más obstinadas y tenaces pueden encontrar aquí la libertad.",
  str_loading_h_desc2 = "Solo pasando a través de vientos amargos y lluvia implacable se puede llegar al ojo de la tormenta de Red-Eye Gorge.\nLa ceniza volcánica que una vez devastó la tierra ahora actúa como fertilizante, llenando de vida esta extensión verde.\nEs casi como si la tragedia de hace mucho tiempo nunca hubiera tenido lugar.",
  str_loading_h_desc3 = "La atmósfera de este laboratorio subterráneo de hormigón es muy aburrida y deprimente.\nLas herramientas quirúrgicas están regadas por las encimeras abiertas, sus contornos fríos y desalmados reflejan un destello de luz amenazante.\nPero es solo desde un lugar así donde florecen las flores más hermosas.",
  str_loading_h_desc4 = "En la memoria de Eve, los cielos de su ciudad eran de azul brillante y sin nubes.\nSi las cosas no hubieran cambiado tan así, ese fugaz momento de felicidad podría haber durado para siempre.\nPero solo tal vez...",
  str_loading_h_desc5 = "En las profundidades de un oasis del desierto de Rediesel, existe una calle construida por Rediesel Wrench.\nAunque la calle parece deteriorada, cada ladrillo en ruinas está lleno de amor.\nEsta humilde extensión de tierra es el lugar más tierno del mundo.",
  str_loading_h_desc6 = "El Hotel Rising Tide, el destino de vacaciones de la nobleza de Lumopolis.\n¡Es simplemente el mejor lugar para disfrutar del bello paisaje de la Costa Celestial!\nActualmente, las reservas están disponibles con un descuento por tiempo limitado.",
  str_loading_h_desc7 = "El Soberano del Océano es una ceremonia de sacrificio originada por los Aurorians que alguna vez vivieron en esta costa.\nLos participantes deben aceptar varias pruebas y completar desafíos difíciles.\nSe cree que su triunfo traerá la bendición del buen tiempo y abundancia de peces.",
  str_loading_h_desc8 = "Una antigua leyenda habla de un castillo que surgió del mar.\nPara salvar a su pueblo, un monarca aceptó las pruebas de las diosas. El tiempo ha pasado, la crisis ha pasado hace mucho tiempo, pero el Rey no ha regresado.",
  str_loading_h_desc9 = "No está claro quién quiso que existiera este dominio, pero es un vacío lleno de visiones extrañas.\nDentro de ella se encuentran aquellos que buscan ciegamente el poder de los valientes perdidos y aquellos que anhelan la oportunidad de escapar de su esclavitud.\nAcepta tu maldición y derriba sus muros.",
  str_loading_h_desc10 = "Caroline se enfrentó a la derrota y maldijo a todos con sus últimas fuerzas. Y el Monarca al que anhelaba resucitar puede que haya escuchado su súplica.",
  str_loading_h_desc11 = "Es hora de que los gorrones se muevan de nuevo. Estos ladrones sombríos emergen de la oscuridad, solo para regresar a las sombras tan rápido como aparecieron.",
  str_loading_h_desc12 = "En el páramo del desierto yermo hay una torre de vigilancia de Subciudad de Illumina. Ha estado aquí desde que Illumina estableció esta Subciudad y la Línea Defensiva, presenciando las incansables luchas de los inflexibles soldados de Illumina.",
  str_loading_h_desc13 = "Este es el campo de batalla en las afueras de Subciudad. Los soldados de Illumina han construido fortificaciones aquí que se dice que son capaces de detener los avances de la mayoría de los atacantes Eclipsites.",
  str_loading_h_desc14 = "Esta estación de transporte se encuentra a las puertas de la Subciudad 24, y es donde se manejan las mercancías que entran y salen de la ciudad. Aunque nadie trabaja aquí ahora, desde las torres elevadoras, los vehículos de transporte y la amplia gama de mercancías, se puede ver que la gente aquí vive una vida activa y ordenada.",
  str_loading_h_desc15 = "Una Subciudad abandonada de Illumina, devastada por un enorme incendio. Los civiles que una vez vivieron aquí fueron evacuados, y los soldados que vivían aquí ahora luchan en la línea del frente. Cada antiguo habitante sigue luchando para cumplir con su deber, decidido a regresar algún día a su hogar.",
  str_loading_h_desc16 = "En Illumina, incluso los pasajes poseen una lucidez radiante, brillando con la luz del acero. Al ver este pasaje por primera vez, uno no puede evitar comentar lo brillante que es.",
  str_loading_h_desc17 = "Durante esta fiesta, los Celestitas practicaron todo tipo de interesantes costumbres y decoraron sus casas.\nCreían que podían conectarse con la naturaleza y sus antepasados a través de estas costumbres.",
  str_loading_h_desc18 = "La historia es como una pluma, atrapada bajo una pesada cáscara.\nEl camino hacia el futuro depende de cómo naveguemos por la carretera.",
  str_loading_h_desc19 = "Libre comercio en un mercado libre: cualquier cosa puede negociarse en Umbraton.\nLos gremios son la encarnación del comercio y el capital, aportando una vitalidad ilimitada a Umbraton.",
  str_loading_h_desc20 = "Las bandas clandestinas de Umbraton se conocen como \"sombras en la sombra\". Operando dentro del área gris, no pueden permitirse el lujo de exponerse a la vista del público. Sin embargo, sueñan con usar su subversión furtiva para convertirse en un éxito de la noche a la mañana, aceptado en la sociedad en general. Cuando las nubes oscuras se forman en lo alto, comienzan a poner en movimiento todo tipo de operaciones secretas...",
  str_loading_h_desc21 = "La Presa de las Cicatrices se mantiene alta y orgullosa a través de desastres naturales o manufacturados, tormentas de lluvia o guerras. No solo ha demostrado su tenacidad a su constructor, el Señor Sombrío, sino que también ha aportado una gran sensación de seguridad a la gente de Umbraton.",
  str_loading_h_desc22 = "Los nobles de Lumopolis exhiben su riqueza con orgullo, aunque su suntuosa exhibición de lujo nace del arduo trabajo de las masas comunes que habitan en la ciudad debajo de Lumopolis. Aunque es un mundo aparte de los señoríos de la nobleza, la vida fluye hacia adelante con una vitalidad cálida y resuelta. Después de todo, esto sigue siendo parte de Lumopolis. Incluso con un estatus más bajo, la gente está mucho mejor que aquellos que viven fuera de los confines de la ciudad.",
  str_loading_h_desc23 = "Como centro de la civilización Aurorian, Lumopolis se considera el líder de las fuerzas del continente. Por esta razón, este salón fue construido para mostrar la fuerza y la gloria de Lumopolis a los líderes extranjeros invitados a la ciudad para participar en reuniones de importancia mundial. De esta manera, Lumopolis mantiene la ventaja en todas las conferencias a las que asisten estas diversas fuerzas y toma una miríada de decisiones que influyen en todo el continente de acuerdo con sus ideales.",
  str_loading_h_desc24 = "Los fuegos artificiales del festival envuelven totalmente de la Azurite. Bajo una exhibición brillante, la gente se reúne y disfrutan de una\ncelebración. Como centro de la civilización en Astra, Lumopolis se merece ese día. Pero todos los días deben llegar a su fin.",
  str_loading_h_desc25 = "El clima en Northland hace que la nieve se acumule durante todo el año. Para las personas que viven en esta área, el bosque cubierto de nieve es un espectáculo familiar. Cuando la luz del amanecer brilla sobre las copas de los árboles cristalizados en hielo, los miles de rayos de luz que se refractan continuamente se convierten en el símbolo de la fe para los residentes de Northland.",
  str_loading_h_desc26 = "Muchas personas afirman que es un lago glacial natural, pero es imposible explicar cómo surgió este lago profundo, tranquilo, suave como un espejo y perennemente congelado. Por lo tanto, muchas personas creen que la formación de Lago Espejo es un regalo del cielo. Se dice que cuando la familia real de Northland viajó a este lugar, tuvieron una visión: una visión de narcisos floreciendo alrededor del Lago Espejo, realzando aún más el misterio de este lago.",
  str_loading_h_desc27 = "Se dice que el guardián que protege Northland es el primer rayo del amanecer en el borde del horizonte, que disipa la oscuridad invasora de la tierra de la noche eterna. Sin embargo, en otras leyendas, el verdadero poder de Northland radica en el juramento y la determinación de proteger este lugar. Ambos son más fuertes que cualquier aurora brillante, cualquier amanecer glorioso, y son perdurables y eternos.",
  str_loading_h_desc28 = [[
Ruinas enteras, completamente aisladas del mundo y llenas de edificios nunca antes vistos.
No parece haber rastro de los habitantes originales.]],
  str_loading_h_desc29 = "Por razones desconocidas, las ruinas se están derrumbando rápidamente.\nTanto las máquinas que están ocupadas reparando las ruinas como los Eclipsites que viven dentro se han vuelto volátiles.",
  str_loading_h_desc30 = "Todavía hay muchos secretos sin resolver en esta ciudad.\nA menos que todos ya tengan una respuesta en sus corazones...",
  str_loading_h_desc31 = "Este núcleo de energía ha estado funcionando durante años sin medida. Está luchando como un paciente moribundo. Cada latido del corazón bien podría ser el último.",
  str_loading_h_desc32 = "Centro de datos de Abby. Este loco módulo biológico está constantemente produciendo y mejorando eclipses. Sus gritos irascibles y horribles han rondado el centro.",
  str_loading_h_desc33 = "Una pequeña isla al este de Astra que es rica en recursos y tiene relativamente pocos eclipses. Hace un siglo, Koufu-jou fue construido en el centro de la Isla de las Nubes y la isla principal envió a un general para gobernar el lugar. Desde entonces, las dos islas han estado enfrentadas. Detrás de un pasado temido por los nativos de Cloud Island, este general está a punto de llevar sus secretos y Cloud Island a un futuro imprevisible...",
  str_loading_h_desc34 = "El tradicional Festival de Primavera de Cloud Island se ha conservado a través de las mareas del tiempo. Aunque la historia y las generaciones han cambiado, los cerezos en flor siguen siendo los mismos.",
  str_loading_h_desc35 = "Las Fiestas Nocturnas son un evento especial en Koufu-jou, que se lleva a cabo en memoria de los espíritus difuntos. Cuando los cerezos están floreciendo, la gente organiza el Festival Kasuga todos los años. Todos se disfrazan, usan una máscara de gato y una linterna, marchando por la calle por la noche. Creen que pueden conectarse con el mundo del más allá de esta manera y ver a sus seres queridos fallecidos una vez más.",
  str_loading_h_desc36 = "Koufu-jou está en el lugar más alto de la Isla de las Nubes. Cuando la gente levanta la vista del resto de Cloud Island, parece como si estuviera anidado en las nubes, lo que se suma a su misterio y solemnidad. Los antepasados de la Isla de las Nubes construyeron Koufu-jou ladrillo a ladrillo hace años, pero hoy, el fuego abrasador lo consumió todo salvajemente. Fue entonces cuando la gente comenzó a pensar en lo que realmente querían. Ahora, ¿quién saludó la guerra y cuántos perecieron en las llamas ardientes?",
  str_loading_h_desc37 = "Los muertos vivientes toman formas durante las horas de Yin, creando un campo de fuerza que atormenta a Cloud Island, mientras que el artefacto divino formado durante las horas de Yang posee el poder Yang puro para eliminar todos los espíritus malignos. Sin embargo, cuando Yin y Yang están en manos de una persona codiciosa y egoísta, los deseos desenfrenados se transforman en algo más aterrador que los fantasmas.",
  str_loading_h_desc38 = "Situado en la parte sur del desierto de Rediesel, vendavales implacables cubren su entorno con una neblina amarilla abrasadora hasta donde alcanza la vista, puntuada solo por huesos blancos y árboles muertos sin rastro de vegetación a la vista. Pero incluso en este lugar sombrío y desolado, todavía hay señales de vida. Además de los escorpiones bengala y las serpientes de anillos carmesí que se esconden en las sombras de las rocas, hay depredadores aún más grandes que acechan en el mar de arena. Este es un lugar donde los débiles son tragados enteros.",
  str_loading_h_desc39 = "La tierra alrededor del volcán está llena de arenisca negra en bruto. Visto desde arriba, la lava ardiente fluye por las fisuras de la montaña, formando una espectacular cascada de lava al borde de un barranco. Cuanto más se acerca uno al volcán, más caliente se vuelve el aire, lo que dificulta la respiración. Lo que es aún más sorprendente son las piezas más pequeñas de arenisca que flotan en el aire debido a fuerzas misteriosas.",
  str_loading_h_desc40 = "Blazing Tooth Canyon, cerca del borde de Eternal Night, recibe su nombre de su paisaje irregular. Sus laderas empinadas parecen hundirse en el suelo donde un río, secado hace mucho tiempo bajo el sol abrasador, serpentea y está cubierto de tantas grietas que difícilmente puede llamarse un camino. Pero tal vez sea porque estas características actúan como obstáculos tan insuperables que se designó como la ubicación de la primera pista de rally de Rediesel Wrench...",
  str_loading_h_desc41 = "Para ocultar una habitación, cubra la puerta con ladrillos y tejas y llene las ventanas con arena y barro. Conviértelo en parte de una calle o pared insignificante y bórralo del mapa para siempre. Un rincón de este mundo se ha ido pero nadie lo sabe. Está reservado exclusivamente para la Orden Verdadera. Lumopolis es muy grande, donde un agujero como este pasa fácilmente desapercibido.",
  str_loading_h_desc42 = "De pie detrás del grueso telón antes de que comience el espectáculo, debe contener los latidos de su corazón, ya que este escenario no permite que nadie se detenga una vez que se abre el telón. La respuesta a una actuación perfecta se encuentra solo en su próximo intento.",
  str_loading_h_desc43 = "Es seguro decir que los títeres están desprovistos de vida y alma. Pero cuando adopta una pose viva, puede hacer que uno piense que es más humano que los vivos mismos. Tal vez sea porque fantaseamos con que objetos como esos tienen alma.",
  str_loading_h_desc44 = "Si hay algo que representa a Eraveil, es el diente de león. Estas pequeñas flores blancas y esponjosas crecen por todo Eraveil, y una ráfaga de viento es todo lo que se necesita para crear la ilusión de nieve que cae. A algunos no les gustan los dientes de león porque sienten que les falta fidelidad, echando raíces siempre donde los lleva el viento. Pero en Eraveil, encontrará que no importa en qué dirección sople el viento, siempre se pueden ver grandes grupos de dientes de león suspendidos en el aire. Van y vienen con el viento, pero siempre han permanecido.",
  str_loading_h_desc45 = "Eraveil es un lugar sereno donde los suaves vientos soplan sobre interminables llanuras verdes y el aire siempre es refrescante. A pesar de eso, la vista se vuelve cansada y evoca un vacío que se siente en el fondo, como si faltara algo. ¿Dónde están los gallos cantando al amanecer, y el humo saliendo de las chimeneas en las tardes?",
  str_loading_h_desc46 = "Siguiendo a la guía, regresas a Eraveil, un lugar con muchos recuerdos familiares.\nDebajo de Eraveil, sin embargo, yace un secreto.\nEste secreto es sobre Eraveil, el pasado y el futuro, y sobre ti.",
  str_loading_h_desc47 = "¡Escondida en el vasto espacio debajo de la Torre Blanca hay una entrada que conduce bajo tierra!\nEs posible que seas el primero en desbloquearlo nuevamente después de miles de años.\nExplora las profundas ruinas subterráneas... Y allí, puedes encontrar lo que has estado buscando.",
  str_loading_h_desc48 = "El misterioso dispositivo en forma de anillo en el centro de la \"Base de mantenimiento Colossus\" debajo de Eraveil parece ser el centro de control de toda la base que mantuvo el vasto complejo en funcionamiento todo este tiempo.\nSin embargo, no parece que se haya mantenido durante mucho tiempo y no estoy seguro de si todavía funciona...",
  str_loading_h_desc49 = "La existencia de la torre blanca en Eraveil es un secreto en sí mismo.\nLa altísima Torre Blanca resuena con tecnologías antiguas que aún existen en la actualidad. ¿Esta resonancia representa una amenaza del pasado o una esperanza para el futuro?",
  str_loading_h_desc50 = "El misterioso dispositivo en la base subterránea de Eraveil parece tener el poder de transformar aurorianos. Se pierde el conocimiento de cómo funciona, y nadie sabe lo que realmente puede hacer. Para usarlo, uno debe considerar los riesgos involucrados...",
  str_loading_h_desc51 = "Regresaste aquí para usar el \"Acorde de la Ley\".\nAunque este camino puede resultar demasiado difícil para un Caelestite, vale la pena aferrarse incluso a la más mínima esperanza.",
  str_loading_h_desc52 = "Atmósfera armoniosa y paisaje natural... Para un Caelestita, no hay mejor patrimonio que los Jardines de las Nubes. Hay muchas cosas con las que lidiar en este enorme patio en la Torre Blanca. Cada existencia insignificante en tus manos se convertirá en parte del futuro que pertenece a Caelestite.",
  str_loading_h_desc53 = "La Fuente de la Esperanza frente a la Torre Jacinto es el corazón de los Jardines de las Nubes. Puedes charlar con tus amigos, liberar los peces que has pescado en el estanque o lanzar una brillante moneda de esperanza al estanque para pedir un deseo resplandeciente.",
  str_loading_h_desc54 = "La sala más común en Cloud Gardens. Tiene buena iluminación y excelente ventilación, lo que lo convierte en un espacio perfecto para vivir o almacenar. Eso sí, recuerda limpiarlo bien antes de usarlo.",
  str_loading_h_desc55 = "Debajo de la colcha bien puesta hay ropa sucia que no se ha lavado en una semana. El armario apretado está lleno de tazas que están a punto de caer. Crunchy Munchy Crunchy a medio comer, libros y revistas están esparcidos por todo el lugar... ¿No es esto normal en la habitación de un niño?",
  str_loading_h_desc56 = "\"No hay familia eterna, sino solo ganancias\". Como muchas familias anticuadas en Umbraton, cada ladrillo y teja de la casa de la familia Andersen se construyó con enormes ganancias. El Conde Andersen actual, sin embargo, parece tener diferentes preferencias de inversión.",
  str_loading_h_desc57 = "Haz que los invitados de tu familia se sientan como en casa e inspira miedo a los enemigos de tu familia. La orden del maestro debe llevarse a cabo pase lo que pase. Sin embargo, las personalidades del mayordomo y del maestro son iguales: el mayordomo de élite de la familia Andersen es perfecto y no muestra piedad, incluso cuando está poniendo a prueba a su maestro.",
  str_loading_h_desc58 = "Las bestias maravillosas generalmente se encuentran lejos de las personas, viviendo libremente en las montañas, bosques, desiertos, campos nevados o en las profundidades del océano. A diferencia de los animales normales, pueden usar Lumina y tienen varias habilidades o características únicas. Estas criaturas amigables rara vez interactúan con los aurorianos, pero a menudo ayudan cuando se enfrentan a una crisis.\nSin embargo, al mismo tiempo, los cambios en sus hábitats y sus propias deficiencias reproductivas han llevado a una disminución en su población general, y muchas bestias maravillosas ahora están en peligro de extinción.",
  str_loading_h_desc59 = "Donde aparecen bestias maravillosas, también encontrarás a los extrozoólogos cerca. Aunque son mucho más raros que las bestias maravillosas, son increíblemente apasionados por su trabajo. Siguen los rastros de bestias maravillosas hasta los confines del mundo, mantienen un registro de su ecología y características, y compilan estos registros en libros como su legado. También ayudan a las maravillosas bestias cuando están en peligro.\nFia está en camino de convertirse en una extrozoóloga a través de sus propios esfuerzos.",
  str_loading_h_desc60 = "El paradero de The Illusionist & Old Bill's Circus siempre ha sido desconocido. Recientemente, se dice que han sido invitados a la famosa ciudad portuaria, Harbor City. El maestro de ceremonias, Jeno, es una persona excéntrica y todos sus subordinados tienen habilidades únicas. Quiere dar a los ciudadanos locales un gran festival de verano para recordar.",
  str_loading_h_desc61 = "El señor de la ciudad de Harbor City parece bastante obsesionado con la Esmeralda. ¿Qué podría haber allí? ¿Qué secretos se esconden? El ajetreo y el bullicio de la celebración pronto disminuirán, y el trasfondo latente debajo de la cubierta pronto surgirá...",
  str_loading_h_desc62 = "El caos creado por Elvis parece haber llegado a su fin después de su arresto, pero nadie sabe realmente por qué hizo todo esto. Las dudas en el corazón de Carleen la hicieron tan sombría como el clima en Harbor City. ¿Cuándo saldrá a la luz la verdad? Para llegar al fondo de esto, Carleen y su grupo se han quedado en Harbor City para realizar investigaciones. Mientras tanto, parece que Elvis aún no ha decidido su plan.",
  str_loading_h_desc63 = "El antiguo sello ha sido sacudido, despertando al legendario Eclipsite durmiendo bajo las profundidades del mar. Una guerra en la costa está a punto de estallar cuando las olas avanzan hacia Harbor City. Ante la inminente batalla con Eclipsites, ¿podrá el grupo proteger Harbor City? ¿Encontrará Elvis una solución a esta crisis?",
  str_loading_h_desc64 = "El Cloudwhale disipó el Darkflow que impregnaba el aire y atravesó las nubes oscuras que envolvían Harbor City. Cuando el sol brilló en Harbor City, parecía que todo había mejorado, e incluso el viento aullador parecía mostrar signos de detenerse.",
  str_loading_h_desc65 = "Los eclipses invadieron hace 12 años.\nDespués de innumerables batallas infernales, esto es lo que quedó de Euphoria.\nHeridas que nunca sanaron, enconándose gradualmente.",
  str_loading_h_desc66 = "Este pueblo está cargado con demasiados pecados del pasado.\nCrecen como tumores en un cuerpo y deben extirparse para recuperarse.\nQuizás solo entonces la luz del sol regrese a este lugar.",
  str_loading_h_desc67 = "—Así se anunció en el periódico. Este edificio en las afueras de Umbraton ha tenido innumerables propietarios a lo largo de los años. Solo recientemente pasó a manos de los Andersens, quienes la convirtieron en la casa encantada que es hoy. Supuestamente fue construido por un arquitecto excéntrico que fue el autor intelectual detrás del diseño de la escalera falsa, puertas y ventanas fuera de lugar. Todos los extraños candelabros y pinturas eran de su propio diseño.",
  str_loading_h_desc68 = "Un sótano peculiar descansa debajo de lo que ahora se conoce como la Casa Embrujada de Andersen. Sé que nunca lo has visto por ti mismo. Es posible que incluso el propietario actual nunca lo haya visto. El último dueño de la casa pisó allí solo una vez y vendió el lugar poco después antes de mudarse muy, muy lejos. Hay muchos rumores en torno al sótano, pero no me creo ninguno. Después de todo, los vivos no tienen forma de saber la verdad.",
  str_loading_h_desc69 = "El Centro de Investigación Illumina es el centro de ciencia y tecnología de la Federación Illumina.\nLos investigadores aquí son responsables de analizar dispositivos tecnológicos antiguos e innovar nuevas tecnologías.\nSin embargo, no hay fin a la investigación. ¿Encontrarás la información que buscas aquí?",
  str_loading_h_desc70 = "El simulador de campo de batalla creado por Illumina Research Center puede llevarte a cualquier batalla registrada en su sistema.\nNo dudes de la autenticidad de las escenas que te evoca: los soldados desesperados, los Eclipses feroces, el sol eclipsado por las llamas de la guerra... Todo lo que ves aquí sucedió realmente.",
  str_loading_h_desc71 = "Los números y la ciencia son incomprensibles y distantes. Lo extraño es que pueden presentar abruptamente emociones e intenciones de una manera incomparablemente precisa frente a nosotros. Algunas distancias son en realidad aún más aterradoras una vez que se pueden medir.",
  str_loading_h_desc72 = "Un lugar donde el sol de Lumopolis no brilla, fuera de la línea de defensa de Entrañas de Illumina. Este pueblo es el último lugar donde se reúnen los Aurorianos. Independientemente de su estatus y diferencias étnicas, los residentes aquí se fusionaron en una fuerza unificada contra el enemigo para proteger la cultura oculta en este pequeño pueblo.",
  str_loading_h_desc73 = "Estos caballeros de las tierras fronterizas son diferentes a los de Lumopolis. Ruedan tanto en el campo de batalla que la arena tiñó la seda blanca que usaban en un color diferente al de Lumopolis. Están más acostumbrados a seguir el filo de sus espadas que a arrodillarse ante la corona.",
  str_loading_h_desc74 = "El Coloso que se estrelló aquí es tan grande.\nUna vez voló libremente con alas que podían cubrir los cielos.\nPero ahora mira en dirección a Eraveil, destinado a nunca volver allí.",
  str_loading_h_desc75 = "Un Coloso equipado con pantallas gigantes y equipo de audio de arriba a abajo.\nLos arqueólogos afirman que cuando celebraban sus festivales, los Caelestites hacían volar a Eulogoz hacia el cielo y transmitían canciones de celebración e imágenes de bailes a través de Eraveil.\nSin embargo, según los datos restantes, Eulogoz y su navegante desaparecieron misteriosamente juntos hace unos cien años.",
  str_loading_h_desc76 = "Una bestia maravillosa que puede vivir para siempre.\nHay muy poca información histórica sobre el Ouroboros, y muchos extrozoólogos creen que el Ouroboros es, de hecho, una mera invención.\nSin embargo, Vic cree firmemente que existe y cree que existe una conexión inexplicable entre él y esta bestia maravillosa.",
  str_loading_h_desc77 = "Un Ouroboros dentro de su huevo puede tejer sueños según su propia voluntad y hacer que los sueños ciclen continuamente hasta que pase su largo período de incubación de manera segura.\nEn el pasado, personas con motivos ocultos irrumpieron deliberadamente en el sueño de un Ouroboros para tratar de evitar que eclosionara para poder alcanzar la vida eterna en su sueño, pero todos fallaron sin excepción.\nPor eso debes pensarlo dos veces antes de entrar en el sueño de un Ouroboros.",
  str_loading_h_desc78 = "Shadowind atraca en Twin Pavilions Bay y trae buenas nuevas a los nativos de Longzhou que habitan allí. La ruta que navega Shadowind conecta Longzhou y Astra y se ha convertido en una línea importante para el intercambio cultural mutuo y el comercio entre las dos regiones. Estos barcos viajan de un lado a otro, cargados con bienes únicos, manjares y tesoros de Longzhou, y brindan un pasaje a casa buscado durante mucho tiempo para aquellos que se han quedado varados lejos de casa.",
  str_loading_h_desc79 = "El mar no se rinde ante un ejército bien preparado, ni se apiada de un pez que mueve la cola. Cuando golpea la tormenta, simplemente experimentas los infinitos años de su existencia en un solo momento. Cuando se encuentran en el mismo centro de la tempestad, los marineros a menudo rezan al pez serpiente, deseando sufrir destinos similares, sumergirse sin miedo en las profundidades del océano y luego trasladarse con seguridad a las aguas poco profundas de su ciudad natal.",
  str_loading_h_desc80 = "El barco hundido yace en silencio en el fondo del océano, más sereno en este momento que en cualquiera de las veces que flotó sobre las olas. El mar se traga todo sonido, ahogando los gritos de vida y dejando solo una visión del final: una fotografía descolorida arrastrada a la orilla. El mar es ilimitado. Puede haber muchos cementerios de barcos como este, pero nadie rinde homenaje a esas tumbas. Esos son los gritos que el mundo ha extrañado.",
  str_loading_h_desc81 = "Llegar a su nivel y juzgar lo que ha hecho o dejado de hacer sería ridículo. No tiene que explicar nada a nadie, por lo que todos sus problemas son solo suyos, y su actitud es lo único que importa. No siente arrepentimiento; en cambio, algo más insensible: la culpa. Usar a una persona para compensar los pecados de cien personas... su culpa viene sin elección propia, pero le da paz de conciencia.",
  str_loading_h_desc82 = "Cuando se trata de celebrar el Día de la Corona de Luna, existen diferentes costumbres en todo el continente.\nEn Illumina, son relativamente discretos y pragmáticos. Expresan su amor dando rollos de canela a sus amores.\nEn Lumopolis, se enfocan más en el sentido de la ceremonia y se regalan preciosos tréboles rojos para representar su sinceridad.\nEn Northland, celebran con sencillez, regalando pequeñas botellas llenas de agua del lago Mirror como recuerdo, que representan el amor puro.",
  str_loading_h_desc83 = "Un atrapasueños meticulosamente tejido, un exquisito colgante de topacio, un tapiz que alguna vez fue objeto de colección entre la nobleza...\nSe siente como si estuviera entrando en una exquisita tienda de antigüedades en lugar de en una oficina de Courier Union.\nTodo aquí parece demostrar que el dueño de esta sala tiene un gusto excepcional.\nLa mayoría de las personas en el desierto de Rediesel son fanáticamente frugales, pero Jeriah exige solo lo mejor en términos de calidad de vida y estándares estéticos.",
  str_loading_h_desc84 = "La región central del Desierto Rediesel está salpicada de oasis, como estrellas dentro de una vasta galaxia de arena roja.\nLas preciosas aguas del desierto han alimentado innumerables vidas, pero han dado lugar a terrores inimaginables, entre los cuales el más famoso es el gusano de arena.\nEstos gigantes siempre están al acecho en la arena esperando, listos para atacar cualquier cosa que pase.",
  str_loading_h_desc85 = "Según las costumbres de todo el continente, el Día de la Corona de la Luna es un día para que los amantes expresen sus sentimientos, por lo que muchas personas celebran bodas en este día.\nPara los nobles más tradicionales, los mensajeros llevan la felicidad a las bodas. Algunos incluso gastan cantidades excesivas de dinero invitando a estos mensajeros a asistir.\nPara disuadir este tipo de comportamiento, que afecta severamente la eficiencia del trabajo de los mensajeros del continente, el Sindicato de Mensajeros ha estado promoviendo otras actividades en un intento de eliminar gradualmente esta tradición.",
  str_loading_h_desc86 = "Bajo el asesoramiento de Schwartz, el Salón de Justicia ha abierto una división temporal para tratar disputas amorosas recientes en esta época especial del año con el fin de garantizar la seriedad de los juicios del tribunal principal. Entrar en la División Romance es como sentarse en un carruaje cuyas ruedas no dejan de girar. Antes de que caiga el mazo del juez, asegúrese de sacar a la luz las pruebas más críticas.",
  str_loading_h_desc87 = "El entusiasmo por el Día de la Corona de la Luna claramente aún no ha disminuido en Lumopolis, ya que un grupo de entusiastas de la Corona de la Luna está organizando un salón de amor improvisado. Marcado por el lanzamiento de globos aerostáticos en forma de luna, tanto plebeyos como nobles se reúnen bajo la luna para bailar, mezclarse y disfrutar de los himnos de la temporada. Aquí es también cuando tanto los sentimientos efímeros como los eternos pueden florecer en un abrir y cerrar de ojos.",
  str_loading_h_desc88 = "No hay nadie en Lumopolis que no conozca la Escalera a los Cielos. Con toda la gente que pasa y visita este lugar, innumerables caminos conducen a la Escalera a los Cielos, siempre te encontrarás caminando por uno de ellos. En esta ciudad claramente estratificada, esta larga escalera tiene muchos significados más allá de un simple \"camino\". Al subir esos escalones de niño, uno puede ver las estrellas; trepando por ellos de adulto, se puede incluso llegar a los Jardines de Lumopolis.",
  str_loading_h_desc89 = "Repensemos lo que significa \"justicia\". No tiene una definición precisa. Generalmente, la mayoría de la gente cree que \"justicia\" significa hacer lo correcto. Estas personas eligen representantes para que hablen por ellos, y estos representantes condensan sus opiniones en votos. ¿Has descubierto el resultado inevitable de este sistema? La estructura de nuestra sociedad está condenada a definir \"justicia\" por el número de votos emitidos, así que ahora soy \"justicia\".",
  str_loading_h_desc90 = "A instancias del Señor de las Sombras, el Orfanato Umbraton ha sido reconstruido en su sitio original.\nAl igual que el Umbratón del pasado, el antiguo orfanato era un pozo negro de corrupción, desprovisto del más mínimo atisbo de esperanza.\nEl fuego arrasó con el pasado, y el sol brilló sin miedo sobre el nuevo suelo debajo.",
  str_loading_h_desc91 = "Hati creció aquí con su madre.\nAunque no le permitieron salir a la calle, tuvo una infancia feliz, bañada en amor maternal.\nEl pony que su madre cosía para ella era su único compañero de juegos cuando era niña, y su colorido libro ilustrado era el tesoro rebosante de su imaginación.\nPero ahora, todo se ha ido.",
  str_loading_h_desc92 = "La Ciudad Subterránea una vez no estuvo registrada y sin nombre, pero alguien se hizo cargo de ella y la reconstruyó hace muchos años.\nMás tarde pasó a llamarse \"Undercity X\" y luego \"Instituto X\" después de que se establecieran una serie de instalaciones de investigación.\nDesafortunadamente, el lugar finalmente fue destruido por un incendio.",
  str_loading_h_desc93 = "Bajo la jurisdicción del profesor Ulysses de Illumina, el Archivo almacena gran cantidad de información confidencial.\nSe desconoce el peso de la historia detrás de cada delgada pieza de datos, dejando enterrada la verdadera profundidad de los secretos.",
  str_loading_h_desc94 = "El método de modificación más efectivo descubierto hasta ahora es combinar varios métodos de mejora que han demostrado ser exitosos en el mismo sujeto experimental.\nSolo necesitamos una mente fuerte para producir un resultado exitoso.",
  str_loading_h_desc95 = "El Ejercicio Militar tiene como objetivo proporcionar un escenario para que todos los participantes aprendan, cooperen y compitan.\nHay dos etapas: preparación del curso y evaluación final.\nEl equipo ganador tendrá la oportunidad de participar en un partido de exhibición con el Gran Mariscal de Illumina.",
  str_loading_h_desc96 = "Nunca se debe dudar del significado de la victoria en la batalla.\nLa batalla encarna la persistencia, la responsabilidad y el heroísmo inquebrantable de cada auroriano frente a la oscuridad mientras nos esforzamos por mantener la luz de la esperanza sin vacilar.",
  str_loading_h_desc97 = "Una bola de cristal especial desarrollada por Boaz, un legendario maestro de adivinación de Northland.\nUna vez activado con Lumina, registra automáticamente todos los eventos que ocurren dentro de un cierto rango del activador a lo largo del día.\nEl activador solo necesita inyectarlo con Lumina una vez más para transportarse a sí mismo o a aquellos que tocan al Cristal de la Memoria Eterna y volver a visitar lo que sucedió ese día.",
  str_loading_h_desc98 = "Para conmemorar la Schwartz contribución de la familia a Lumopolis, la gente de la ciudad decidió espontáneamente realizar una celebración en el día del primer antepasado de la Schwartz familia se convirtió en el Señor de la Ciudad. Con el tiempo, este día se convirtió en una fiesta oficial de Lumopolis.\nEl Schwartz la familia constantemente realiza desfiles, celebraciones, cenas sociales y otros eventos en este día.\nSin embargo, desde la Crisis de Darkover, la escala de las festividades ha disminuido gradualmente.",
  str_loading_h_desc99 = "Hace miles de años, los antepasados de la familia Kartima firmaron un contrato con los dragones. Durante milenios, los draconianos despiertos han dado la bienvenida a sus propios dragones, prometiendo ser siempre leales unos a otros y sacrificar incondicionalmente sus vidas y su poder por los demás. Sin embargo, con el fin de mezclarse con la sociedad auroriana, la familia Kartima llegó a considerar a los dragonantes despiertos como extraños y les prohibió reproducirse. Aún no se ha respondido por qué sus actitudes cambiaron tan repentinamente. Lo único que se puede confirmar es que Mime Kartima, la líder de la familia, convocó nuevamente a los dragones. Pero a partir de ese día, su familia comenzó a decaer por completo.",
  str_loading_h_desc100 = "\"Es posible que tenga muchas preguntas en mente, y no puedo garantizar que tenga todas las respuestas. Este viaje debe ser corto, por lo que le insto a atesorar esta experiencia fugaz por encima de todo\".",
  str_loading_h_desc101 = "Nacido en una familia de individuos altamente educados, Joshua es una mujer notable y bien informada que sobresale en lo académico y en la lucha. Su padre era un erudito muy conocido que instruyó a Daniel cuando era joven. Fue así como se conocieron y eventualmente se convirtieron en una pareja que superó la barrera de clases. La historia de su amor es un clásico de la nueva era de Lumopolis, que inspira a innumerables hombres y mujeres jóvenes con añoranza y expectativas para el futuro. Joshua estuvo a la altura de las expectativas del pueblo, presentándose con una imagen tan perfecta como la de la Santa Madre, lo que aumentó mucho la confianza política del pueblo en la Schwartz familia.\nAsí eran las cosas hasta ese accidente.",
  str_loading_h_desc102 = "Una vez tuvo un nombre propio, pero ahora se llama Joshua o el Niño de Montague. A diferencia del actual Señor de la Ciudad, el anterior Señor de la Ciudad, el padre de Daniel, era un tirano. A través de una tiranía sin precedentes, cambió la clase que había reforzado sus puntos de vista en Lumopolis durante cien años y también purgó a sus oponentes con extrema crueldad. Joshua es un sobreviviente de la Casa Montague.\nAlgunos conspiradores hicieron un argumento basado en estos sobrevivientes para establecer una organización con el objetivo de acabar con el Schwartz familia. Sin embargo, era solo otra lucha política por más poder, y a nadie realmente le importaba el dolor de los sobrevivientes. La ira insaciable en sus ojos es solo una herramienta en los ojos de los demás.",
  str_loading_h_desc103 = "Denuo Wonderland, ubicado en lo profundo del Desierto de Rediesel y rodeado por un tranquilo desfiladero, marca la primera fase del desarrollo del complejo turístico Denuo Valley Resort. \nThe Rediesel Wrench desempeñó un papel importante en el diseño de varias atracciones durante la creación del parque, garantizando una experiencia emocionante y desafiante para todos los visitantes. Cabe destacar que la rueda del cielo permanece abierta durante la noche, permitiendo a los huéspedes disfrutar de un romántico espectáculo de fuegos artificiales mientras la montan.",
  str_loading_h_desc104 = "Ubicado junto al mundo maravilloso, el Hotel Resort Denuo se presenta como un magnífico castillo que surge con gracia del mundo maravilloso. \nEl distintivo paisaje de jardinería en la entrada principal encarna la esencia cultural del Valle de Denuo y el profundo respeto de los desarrolladores por la naturaleza. Cabe destacar las obras de arte hechas a mano exhibidas en el gran vestíbulo y la terraza del hotel, elaboradas por artesanos locales que muestran sus extraordinarios talentos. Todo el hotel es como un museo, relatando la fascinante historia del Valle de Denuo y la encantadora leyenda de la Diosa Denuo para cada apreciado huésped.",
  str_loading_h_desc105 = "El Valle de Denuo se erige como una gema prístina, ostentando una disposición geográfica ventajosa y un pintoresco paisaje natural.\nSegún cuentan las leyendas locales, un misterioso desastre natural azotó alguna vez el desfiladero, borrando del mapa un pueblo entero. Este evento sirvió como un profundo recordatorio de la naturaleza, impulsando a los desarrolladores a priorizar la restauración y preservación ecológica durante todo el proceso de desarrollo. Ahora, el Valle de Denuo prospera como un santuario floreciente, proporcionando un refugio armonioso para una abundante y fascinante fauna y flora.",
  str_loading_h_desc106 = "El Hotel Resort Denuo Valley está equipado con sistemas de purificación de aire de última generación. Para minimizar los ruidos generados durante la circulación del aire, el propietario del complejo siguió el consejo del personal y construyó una cámara subterránea para alojar la maquinaria de gran tamaño.\nPoco saben que, detrás de una puerta secreta en la habitación, hay un túnel misterioso y oculto. Dentro se almacenan objetos que parecen llevar una historia distante y fascinante.",
  str_loading_h_desc107 = "La historia de la Prisión Illumina abarca a través de los siglos, establecida con el objetivo inicial de mantener la seguridad de la federación, penalizar el comportamiento delictivo y fomentar la introspección y la reforma entre los infractores.\nLos reclusos se clasifican en diferentes categorías y niveles dentro de la prisión según su grado de peligro, la naturaleza de sus delitos y la duración de sus condenas. Por lo general, el comité nombra directamente al equipo de gestión de las prisiones de alta seguridad. Cualquier persona que ingrese a estas instalaciones de alta seguridad debe proporcionar documentación válida.",
  str_loading_h_desc108 = "El Bastión Lumo es el hogar de los primeros exiliados de Lumopolis, incluidos caballeros, residentes y sus descendientes, todos gobernados por nobles locales de Lumopolis. El actual Señor de la Ciudad, Dietrich, ha acumulado riqueza en los últimos años a través de la minería de minerales y ha establecido un ejército, lo que le otorga una influencia considerable sobre las ciudades de la superficie de Lumopolis.\nDentro del Bastión Lumo, hay una iglesia independiente y un sector de infraestructura que, durante tiempos de guerra, se comprometen a proteger a los residentes de Lumopolis.",
  str_loading_h_desc109 = "Liberado por el Eclipsite Mudbundle, el lodo contaminado se extiende por la tierra como una marea de obsidiana. Dondequiera que toca la tierra, surge un feroz silbido corrosivo, seguido del desmoronamiento del suelo y el marchitamiento de las plantas. Un poderoso hedor a descomposición permanece en el aire mientras el cenagal se expande rápidamente, atrapando a seres inocentes en su alcance.\nMudbundle se esconde en las profundidades del lodo, capaz de realizar movimientos ágiles y ataques contra los Aurorianos. Por otro lado, los Eclipsites aprovechan el Darkflow dentro del lodo para mejorar su poder ofensivo.",
  str_loading_h_desc110 = "Hasta donde sabemos, el Warp probablemente sea un poderoso Darkflow que proviene del Eclipse. Cada vez que un equipo atrapado en él avanza cierta distancia, siempre se encuentran de vuelta al punto de partida. La verdadera naturaleza de este arte está envuelta en misterio.\nEste \"punto de partida\" se refiere al centro de un espacio circular fijo, limitando el movimiento del grupo dentro de su radio. Esto deja a los Aurorianos con una constante sensación de correr en círculos, atrapados incluso en una ilusión de bucles infinitos.",
  str_loading_h_desc111 = "El Bastión Lumo es el hogar de los primeros exiliados de Lumopolis, incluidos caballeros, residentes y sus descendientes, todos gobernados por nobles locales de Lumopolis. El actual Señor de la Ciudad, Dietrich, ha acumulado riqueza en los últimos años a través de la minería de minerales y ha establecido un ejército, lo que le otorga una influencia considerable sobre las ciudades de la superficie de Lumopolis.\nDentro del Bastión Lumo, hay una iglesia independiente y un sector de infraestructura que, durante tiempos de guerra, se comprometen a proteger a los residentes de Lumopolis.",
  str_loading_h_desc112 = "El diseño de las celdas de la prisión de Illumina sigue los estándares y comodidades establecidos, garantizando una supervisión efectiva de los reclusos y medidas de seguridad. Cada celda proporciona espacio de almacenamiento para que los convictos guarden sus pertenencias personales, desde contenedores pequeños hasta medianos, ropa y materiales de lectura. También se han instalado sistemas de iluminación y ventilación para garantizar la comodidad y seguridad dentro de la celda.\nLas inspecciones y el mantenimiento regulares son fundamentales para las celdas de la prisión, asegurando el mantenimiento continuo de los estándares de seguridad e higiene. Los rumores sugieren que esta instalación también detiene a criminales de otras facciones.",
  str_loading_h_desc113 = "Un dominio que trasciende el ámbito de las entidades materiales, aparentemente accesible solo a través de caminos únicos. Los líderes de la True Order afirman haber recibido revelaciones del Señor de la Verdad en este mismo lugar.\nDentro de este territorio secreto, la diferenciación entre luz y oscuridad se vuelve difícil de percibir, ya que algo brillante en carmesí parece sustituir el medio aéreo habitual, provocando que los Aurorianos que llegan aquí por primera vez experimenten sensaciones indescriptibles: suspensión del cuerpo, compresión intensa y más allá.",
  str_loading_N33_Cname_01 = "Denuo Mundo Maravilloso",
  str_loading_N33_Cname_02 = "Hotel Resort",
  str_loading_N33_Cname_03 = "Valle Denuo",
  str_loading_N33_Cname_04 = "Sótano",
  str_loading_N33_Ename_01 = "Un mundo maravilloso de lujo enclavado en lo profundo del Desierto de Rediesel.",
  str_loading_N33_Ename_02 = "Un resort hotelero ultra-lujoso.",
  str_loading_N33_Ename_03 = "Una región de cañón no desarrollada dentro del complejo Denuo Valley Resort.",
  str_loading_N33_Ename_04 = "Un sótano subterráneo en el hotel, que alberga equipos de ventilación y medidas de insonorización.",
  str_loading_N33_des_01 = "Denuo Wonderland, ubicado en lo profundo del Desierto de Rediesel y rodeado por un tranquilo desfiladero, marca la primera fase del desarrollo del complejo turístico Denuo Valley Resort. \nThe Rediesel Wrench desempeñó un papel importante en el diseño de varias atracciones durante la creación del parque, garantizando una experiencia emocionante y desafiante para todos los visitantes. Como un detalle especial, una vez que se pone el sol, todos los huéspedes están invitados a tomar la rueda del cielo y disfrutar de un espectáculo de fuegos artificiales súper romántico.",
  str_loading_N33_des_02 = "Ubicado junto al mundo maravilloso de Denuo, el Hotel Resort Denuo se presenta como un magnífico castillo que surge con gracia del mundo maravilloso. \nEl distintivo paisaje de jardinería en la entrada principal encarna la esencia cultural del Valle de Denuo y el profundo respeto de los desarrolladores por la naturaleza. Cabe destacar las obras de arte hechas a mano que se exhiben en el gran vestíbulo y la terraza del hotel, elaboradas por artesanos locales que muestran sus extraordinarios talentos. En conjunto, el hotel se asemeja a un museo en miniatura, narrando la historia rica del pueblo de Denuo y la leyenda de la Diosa de Denuo para cada huésped apreciado.",
  str_loading_N33_des_03 = "El Valle de Denuo se erige como una gema prístina, ostentando una disposición geográfica ventajosa y un pintoresco paisaje natural.\nSegún cuentan las leyendas locales, un misterioso desastre natural azotó alguna vez el desfiladero, borrando del mapa un pueblo entero. Este evento sirvió como un profundo recordatorio de la naturaleza, impulsando a los desarrolladores a priorizar la restauración y preservación ecológica durante todo el proceso de desarrollo. Ahora, el Valle de Denuo prospera como un santuario floreciente, proporcionando un refugio armonioso para una abundante y fascinante fauna y flora.",
  str_loading_N33_des_04 = "El Hotel Resort Denuo Valley está equipado con sistemas de purificación de aire de última generación. Para minimizar los ruidos generados durante la circulación del aire, el propietario del complejo siguió el consejo del personal y construyó una cámara subterránea para alojar la maquinaria de gran tamaño.\nPoco saben que, detrás de una puerta secreta en la habitación, hay un túnel misterioso y oculto. Dentro se almacenan objetos que parecen llevar una historia distante y fascinante.",
  str_loading_h_desc10004 = "Eve nació y creció en el Desierto de Reddiesel.\nVive en una comunidad de caravanas con su fuerte padre y su amorosa madre.",
  str_loading_h_desc10005 = "Eve siempre se ha preguntado sobre el nombre peculiar de la calle... pero está bien.\nTiene tiendas geniales y la clínica del médico.\n¡Eso es todo lo que importa!",
  str_loading_h_desc10006 = "En la memoria de Eve, nunca había estado en otro lugar más allá de la zona de caravanas y Tail Street.\nAhora, habiendo abierto la puerta de hierro al mundo exterior por sí misma, sus padres probablemente le darían una lección seria si lo supieran.\nAdemás... mira, el mundo exterior es bastante aterrador en verdad.",
  str_loading_h_desc10007 = "El paisaje cambia continuamente ante sus ojos, como un hermoso pero intangible cuento de hadas, mostrando abruptamente sus colmillos ardientes.\nLa ilusión se derrumbará como montañas eventualmente, así que sigue adelante...",
  str_loading_h_desc20011 = "\"Desde la infancia, Irridon ha albergado un profundo deseo de trabajar en el Salón de Justicia.\nEn cuanto a las razones específicas... parece que incluso Irridon misma tiene dificultades para recordarlas.\"",
  str_loading_h_desc20012 = "\"Las familias nobles de alto rango generalmente no envían a sus hijos a la Dawn Academia para estudiar; en cambio, prefieren contratar los servicios de los tutores privados más excepcionales.\nEl padre de Irridon, sin embargo, se desvió de la norma. Esperaba que Irridon pudiera aprender desde temprano cómo destacarse entre las masas.\"",
  str_loading_h_desc20013 = "\"Desde la casa de Irridon en los Jardines de Lumopolis, hay que dar algunas vueltas y luego bajar por la larga Escalera a los Cielos para llegar al Patio de Lumopolis.\nEn los ojos de Irridon, el Patio no parece muy diferente de los Jardines.\nSin embargo, para muchos de los compañeros de escuela de Irridon, escalar la escalera entre la clase del Patio y la clase de los Jardines era como una misión imposible.\"",
  str_loading_h_desc20014 = "\"Durante los primeros años de Irridon, tuvo pocas oportunidades de aventurarse en la Baja Lumopolis.\nSegún su padre, ese lugar estaba lleno de nobles menores y gente común, lo cual le preocupaba que pudiera influir negativamente en el niño.\"",
  str_loading_h_desc20015 = "Sobre la tranquila superficie del agua, se forman anillos concéntricos de ondulaciones doradas uno tras otro.\nLos reflejos en el agua se distorsionan gradualmente por las ondulaciones, casi como si hubiera un mundo fantástico y colorido allí dentro.",
  str_loading_h_desc80030001 = "Connolly prefiere llamar al lugar \"residencia\" en lugar de \"hogar.\"",
  str_loading_h_desc80030002 = "Las calles parecen estar envueltas en una neblina etérea bajo la luz ondulante y salpicada, con seres acuáticos y residentes que parecen peces vagando por ellas.",
  str_loading_h_desc80030003 = "En comparación con el ático oscuro y frío, el lugar llenó de energía a Connolly y le brindó calidez y apoyo. Para Connolly, finalmente hay un sentido de pertenencia y un lugar al que regresar.",
  str_loading_h_desc80030004 = "Aquí, una fantástica ciudad ubicada en lo profundo del mar que se asemeja al país de las maravillas en los cuentos de hadas.\nConnolly se sumerge en este mundo acuático, ¿logrará navegar a través de las turbulentas corrientes submarinas y encontrarse con amigos cercanos?",
  str_loading_h_desc80040001 = "El lado oeste de Twin Pavilions Bay está gestionado por Umbraton. Esta área es similar a otras ciudades de Astra en términos de estilo arquitectónico, pero se ve más exótica debido a la adición de decoraciones de Longzhou.",
  str_loading_h_desc80040002 = "El lado este de Twin Pavilions Bay está bajo la jurisdicción del Gremio Lin, y hay un distrito llamado Pequeño Longzhou, diseñado para parecerse a Longzhou, junto al puerto.",
  str_loading_h_desc80040003 = "Twin Pavilions Bay tiene varios puertos con un gran número de muelles y barcos. Asume la importante responsabilidad de las operaciones de envío entre Astra y Longzhou y siempre está listo para recibir barcos y cargas de todo el mundo.",
  str_loading_h_desc80040004 = "Hace mucho, mucho tiempo, había un débil espadachín maldito que blandía una gran espada capaz de derrotar a cualquier demonio y vencer a cualquier enemigo. El espadachín no se movía por dinero o fama y estaba en una búsqueda única para encontrar y romper todo tipo de maldiciones extrañas. ¿Podrá ella traer su propio amanecer después de matar todas las maldiciones del mundo?",
  str_loading_h_desc80050001 = "Un héroe valiente y humorístico surgido de los civiles, líder de la Legión Northwind que siempre se sacrifica voluntariamente por el reino y su gente. Pero, ¿alguien ha profundizado realmente en su corazón para entender las cargas que lleva, su angustia milenaria?",
  str_loading_h_desc80050002 = "Antes de que esta tierra se conociera como Astra, albergaba brotes dispersos de las civilizaciones Aurorianas. Entre ellos había un reino, cuyos rastros se han desvanecido en el polvo, pero sus leyendas perduran hasta hoy.",
  str_loading_h_desc80050003 = "Erigida en el centro de la ciudad, una majestuosa estructura consagra las creencias compartidas de todos en el reino. A diferencia de la Lumopolis de hoy, este lugar sagrado no rechazó a los refugiados empobrecidos hace mil años.",
  str_loading_h_desc80050004 = "Solo los verdaderos guerreros pueden entrar en la arena, mostrando su poder ante la multitud, recibiendo una lluvia de flores y aplausos...",
  str_loading_N35_Cname_01 = "Ruinas Subterráneas",
  str_loading_N35_Cname_02 = "Northland",
  str_loading_N35_Cname_03 = "Zarya",
  str_loading_N35_Ename_01 = "Ruinas de una era antigua.",
  str_loading_N35_Ename_02 = "La Tierra de Hielo y Nieve, Origen de los Aurorianos",
  str_loading_N35_Ename_03 = "Doncella Congelada",
  str_loading_N35_des_01 = "Esta ubicación no existe en ningún mapa y está ausente en la mayoría de las guías de exploradores. Estas ruinas están llenas de innumerables peligros, como desafiando a todos los que se acercan a avanzar más. Casi parece que cuanto más profundo vas, más claramente puedes escuchar un sonido mecánico, carente de toda emoción y lo suficientemente aterrador como para hacer que cualquier intruso huya. Si sigues avanzando, ¿qué encontrarás en las profundidades?",
  str_loading_N35_des_02 = "Northland nació en la nieve y perdura a través de la escarcha. Bajo la tutela del Queen, los aurorianos han protegido Northland durante generaciones. Ahora, como en el pasado, incluso si deben sacrificar sus vidas o enfrentar una soledad inimaginable, nunca eluden esta responsabilidad. Pero ten en cuenta que, aunque Northland es el lugar de nacimiento de los aurorianos, no es el lugar de nacimiento de toda la civilización.",
  str_loading_N35_des_03 = "Cien años es más de lo que dura la vida de la mayoría de los Aurorianos, pero para Zarya, las penas y arrepentimientos de un siglo pasado parecen como si hubieran sido ayer. Atrapada en esta implacable tumba de hielo durante cien años, finalmente fue liberada. Sin embargo, ¿quién la salvará del gélido hielo y las dudas persistentes congeladas en lo profundo de su corazón?",
  str_loading_N36_Cname_01 = "Umbraton",
  str_loading_N36_Cname_02 = "Puesto avanzado de Illumina",
  str_loading_N36_Cname_03 = "Desierto de Rediesel",
  str_loading_N36_Ename_01 = "\"Un centro de negocios e inteligencia.\"",
  str_loading_N36_Ename_02 = "\"Repele a los enemigos, abraza a los afines.\"",
  str_loading_N36_Ename_03 = "\"Desierto, el verdadero reino de la libertad.\"",
  str_loading_N36_des_01 = "Ubicado debajo de la Ciudad de Lumopolis, Umbraton es un centro de comercio y finanzas, pero también alberga crímenes, corrupción y engaños. Sin embargo, al interactuar con los lugareños, descubrirás que no todos en Umbraton están moralmente en bancarrota. Hay algunas personas realmente buenas aquí, como el dueño del Restaurante Liu y el jefe del Gremio Cloudrover.",
  str_loading_N36_des_02 = "Esta es una zona crucial para defenderse de los Eclipsites. Los soldados estacionados aquí son responsables no solo de repeler los ataques de los Eclipsites, sino también de proteger a Illumina y realizar patrullas rutinarias en las regiones cercanas y las rutas comerciales. De vez en cuando, estos soldados organizan banquetes de celebración. Independientemente de tus orígenes, siempre que no hayas causado problemas antes o hayas ayudado a Illumina, te extenderán una invitación.",
  str_loading_N36_des_03 = "Dentro de la inmensidad del Desierto de Rediesel, encontrarás muchas criaturas peculiares además de los Eclipsitas, e incluso podrías vislumbrar a los legendarios dragones. Pero aún así, cuando la gente menciona el Desierto de Rediesel, lo primero que viene a la mente es la Rediesel Wrench liderada por Sinsa. Sus miembros recorren frecuentemente el desierto en sus vehículos, llevando una vida despreocupada y agradable.",
  str_loading_c_h_name10001 = "Bahía Twin Pavilions",
  str_loading_c_h_name10002 = "Puerto de Twin Pavilions Bay",
  str_loading_e_h_name10001 = "Un puerto crucial que conecta Astra y Longzhou.",
  str_loading_e_h_name10002 = "Este bullicioso puerto nunca duerme, con barcos mercantes atracando a todas horas.\nEstas embarcaciones, cargadas con el peso tangible de las esperanzas y sueños de la gente, marcan el flujo y reflujo de la vida aquí.",
  str_loading_h_desc10001 = "Situada en la desembocadura del río Gold, Twin Pavilions Bay era una vez un pequeño susurro de pueblo. Su destino cambió irrevocablemente hace años con la llegada del primer barco mercante de Longzhou, iniciando su transformación en una vibrante metrópolis.\nLa ciudad es un estudio notable de contrastes: la mitad este, ubicada junto al mar y al puerto, está bajo la administración del gremio Lin, sus venas arquitectónicas laten con el estilo Longzhou; la mitad oeste, dirigida por Umbraton, presenta una imagen espejo de Umbraton en su paisaje urbano.",
  str_loading_h_desc10002 = "El puerto de Twin Pavilions Bay, moldeado por el incesante flujo de barcos mercantes, tiene un entramado de calles que reflejan el estilo Longzhou, lleno de vida con el palpitar del mercado. Pequeñas tiendas, principalmente refugio para marineros, salpican el paisaje, intercaladas con restaurantes económicos, posadas y ocasionales vendedores ambulantes. El Puente Dorado, una silueta distante, funciona como un hilo unificador entre las mitades este y oeste de la ciudad.",
  str_loading_N37_Cname_01 = "Gremio de Explorador Nublar",
  str_loading_N37_Cname_02 = "Clínica Sin Nombre",
  str_loading_N37_Cname_03 = "Lobos negros",
  str_loading_N37_Ename_01 = "Uno de los gremios más prósperos y famosos en Umbraton",
  str_loading_N37_Ename_02 = "Clínica clandestina de confianza",
  str_loading_N37_Ename_03 = "Pandilla emergente rápidamente en Umbraton",
  str_loading_N37_des_01 = "Un gremio fundado por Sheol.\nEn solo unos pocos años, pasó de ser una tienda móvil desconocida a uno de los principales gremios en Umbraton.\nEl Gremio de Explorador Nublar no logró esa hazaña sin motivo. Después de todo, aquí puedes comprar cualquier cosa que puedas imaginar, y más.\nIncluso tú te has perdido entre sus selecciones, ¿verdad?",
  str_loading_N37_des_02 = "Una pequeña clínica en las remotas barriadas de Umbraton cuya apertura nadie recuerda. El médico y su asistente nunca revelaron sus nombres, así que todos los llamaban \"Médico sin nombre\" y \"Asistente sin nombre\". A pesar del misterio, la gente pobre de los alrededores acude en masa en busca de tratamiento, ya que el médico es bueno y económico.",
  str_loading_N37_des_03 = "En Umbraton, innumerables pandillas pequeñas se han formado por la necesidad de autoprotección, aunque aquellas que no solo se han labrado un nombre sino que continúan expandiéndose como los Lobos Negros son pocas y distantes entre sí.\nAlgunos afirman que los Lobos Negros cuentan con el respaldo de un cierto gremio importante para actuar tan descaradamente como lo hacen, pero la pandilla nunca da una respuesta directa a ese rumor.\nQuizás, es solo porque nadie ha hecho esa pregunta abiertamente.",
  str_loading_N38_Cname_01 = "Bahía Twin Pavilions",
  str_loading_N38_Cname_02 = "Shadowind",
  str_loading_N38_Ename_01 = "Puerto Comercial Bicontinental",
  str_loading_N38_Ename_02 = "Buque Oceánico Mecanizado",
  str_loading_N38_des_01 = "Originalmente un pequeño pueblo de pescadores en el lado este de Umbraton, se ha convertido en un puerto comercial con la llegada de los barcos mercantes de Longzhou. Hoy en día, el lado oeste de la actual Twin Pavilions Bay es administrado por Umbraton, compartiendo estilos arquitectónicos con otras ciudades de Astra. El lado este está bajo el control del gremio Lin, con una calle y puerto de temática oriental similares al estilo de Longzhou.",
  str_loading_N38_des_02 = "Un barco oceánico de última generación financiado y construido por el Lin Guild.\nDiseñado con la adición de maquinaria del Reino de Ye, supera a los barcos tradicionales en durabilidad y potencia. Además, cuenta con un dispositivo para operaciones de rescate submarino. Esta embarcación transportará a navegantes, Xuan Ji y otros hacia el mar profundo, aventurándose en reinos inexplorados.",
  str_loading_N39_Cname_01 = "Gremio de Explorador Nublar",
  str_loading_N39_Cname_02 = "El Pozo",
  str_loading_N39_Cname_03 = "Gremio Continental",
  str_loading_N39_Ename_01 = "Uno de los gremios más prósperos y famosos en Umbraton",
  str_loading_N39_Ename_02 = "Un lugar de entretenimiento para la nobleza.",
  str_loading_N39_Ename_03 = "Un gremio emergente basado fuera de Umbraton.",
  str_loading_N39_des_01 = "Un gremio fundado por Sheol. En solo unos pocos años, se expandió de una tienda móvil sin nombre a uno de los gremios más poderosos de Umbraton.\nHoy, el Gremio de Explorador Nublar incluso posee un enorme dirigible que incorpora viajes, compras, ocio y vacaciones, ¡todo en un solo lugar!\nLa capacidad del Gremio de Explorador Nublar para lograr tales hazañas no es sin razón. Después de todo, cualquier producto imaginable (e incluso inimaginable) se puede comprar a través de ellos.Incluso tú te has perdido en sus considerables selecciones, ¿no es así?",
  str_loading_N39_des_02 = "En la superficie entre Umbraton y Lumopolis existe una gran extensión de tierra conocida en el pasado como \"El Foso\". Hace mucho tiempo, servía como un teatro de deportes sangrientos para los nobles de Lumopolis. \nAquí, arrojaban a cien criminales endurecidos en El Foso y los obligaban a matarse entre ellos para su diversión; la última persona en pie recibiría un indulto total, así como generosas recompensas del noble que los patrocinaba. Con el tiempo, surgieron una serie de luchadores de Umbraton, gladiadores que entraron voluntariamente en El Foso en busca de riqueza y gloria.\nAntes de la Crisis de Darkover, los nobles ya habían comenzado a retirarse lentamente a la seguridad de Lumopolis, y El Foso cayó en declive; sin embargo, su cultura de \"la fuerza por encima de todo\" persistió y se convirtió en el status quo en Umbraton. Pronto, aparecieron por toda la ciudad anillos de pelea ilegales que buscaban imitar la gloria del Pozo, atrayendo enormes cantidades de atención.",
  str_loading_N39_des_03 = "Un gremio a gran escala que ha surgido fuera de Umbraton. Su líder es una mujer misteriosa que rara vez muestra su rostro en público.\nRara vez los gremios ven este nivel de crecimiento rápido sin depender de las ventajas geográficas y logísticas de Umbraton, sin embargo, el Gremio Continental logró alcanzarlo de alguna manera.\nComo su nombre lo indica, la influencia del Gremio Continental se extiende a casi todos los pequeños pueblos y aldeas en la tierra de Astra.",
  str_loading_c_h_name121 = "Laboratorio de Algol",
  str_loading_c_h_name122 = "Antigua Cámara Illumina",
  str_loading_c_h_name123 = "Encima de Ciudad Gannon",
  str_loading_c_h_name124 = "Depósito Cero",
  str_loading_c_h_name125 = "Fisura Desconocida",
  str_loading_c_h_name126 = "Río Prístino",
  str_loading_e_h_name121 = "Una oficina de Illumina que es tanto de alta tecnología como acogedora.",
  str_loading_e_h_name122 = "Un antiguo laboratorio de Illumina envuelto en sospechas y controversias.",
  str_loading_e_h_name123 = "Como el amanecer, pero también como el atardecer.",
  str_loading_e_h_name124 = "Un misterioso almacén fuera de registro en Illumina.",
  str_loading_e_h_name125 = "Fisura hundida y destrozada de profundidad y oscuridad desconocidas.",
  str_loading_e_h_name126 = "Río retorcido y brillante con un encanto enigmático.",
  str_loading_h_desc121 = "Este laboratorio de arquitectura mixta es la oficina privada del científico de Illumina Algol. Un lugar que combina tecnología y comodidad es raro en el Gannon dominado por el ejército.\nAunque el laboratorio no cumple con Las Regulaciones de Illumina para la Gestión de Viviendas, nadie se opuso ya que la mayoría de los muebles fueron construidos por Algol utilizando materiales reciclados. Se dice que cualquiera que visite el laboratorio podría dormir profundamente con los zumbidos electrónicos de fondo.",
  str_loading_h_desc122 = "Hace muchos años, cuando los suministros eran escasos en la Federación Illumina, jóvenes científicos idealistas discutían el futuro de los Aurorians día y noche en este pequeño laboratorio. Si hubiera un fin para los Aurorians, cada discusión y pregunta planteada era para evitar que eso sucediera. Sin embargo, las mesas de laboratorio, el suelo y las estructuras de acero que una vez fueron el reflejo de esa sabiduría han desaparecido desde entonces.",
  str_loading_h_desc123 = "Cuando alguien en Illumina mira hacia arriba en la subciudad, sabe que el rayo de luz penetrante es un regalo del \"mundo civilizado\" para Gannon. Una y otra vez, Gannon ha soportado las incursiones de los Eclipsites, por lo que la gente de Illumina se esfuerza por repeler a los invasores, con la esperanza de que algún día puedan salir a la superficie y disfrutar del sol en paz.\nSin embargo, este rayo también es la despedida final del mundo civilizado. Con la inminente Crisis de Darkover, ¿mantendrá Illumina su hogar?",
  str_loading_h_desc124 = "Un almacén copioso, vacío y frío, impregnado con el olor de las soluciones. El espacio abierto parece haber albergado alguna vez armas enormes pero letales. Aquellos que entran por primera vez nunca se han sentido más insignificantes.\nUna máquina en funcionamiento continuo actúa como un enlace entre el pasado y el presente. Acércate a la intrincada y chirriante mesa de laboratorio biológico y casi puedes escuchar los gritos de las innumerables vidas inocentes que dieron la bienvenida a su \"renacimiento\" aquí.",
  str_loading_h_desc125 = "Una gigantesca fisura sin ningún signo de vida. A juzgar por las grietas, es un fenómeno antiguo de la Zona Oscura. También se evidencian violentas explosiones pasadas, dejando solo un pozo negro como el carbón, guijarros a la deriva y tierra chamuscada. En la superficie, las grietas se ramifican aún más lejos.\n¿Qué ocurrió aquí? O, ¿qué sigue ocurriendo?",
  str_loading_h_desc126 = "Oscuridad interminable y silencio como si el tiempo se hubiera detenido. De repente, un río inescrutable se extiende lentamente desde el remoto \"horizonte\" como en una pintura. Este es un paisaje fantástico nunca antes visto en los mapas de Astra. Su aparición envuelve la realidad del mundo en aún más misterio.\n¿Dónde está la fuente de este río? ¿Es real? ¿Por qué es que cuando agitas el agua, suceden cambios inesperados en algún lugar del mundo?",
  str_loading_c_h_name127 = "Reino de Ji",
  str_loading_c_h_name128 = "Crisis Costera en el Reino de Ji",
  str_loading_c_h_name129 = "Festival de Primavera",
  str_loading_e_h_name127 = "Reino del Comercio y Envío de Agua",
  str_loading_e_h_name128 = "Doncella Dragón, Eclipsites y el Sello",
  str_loading_e_h_name129 = "Año Nuevo de Longzhou",
  str_loading_h_desc127 = "Un reino vasallo en el oeste de Longzhou. Está lleno de numerosos ríos entrecruzados y, como tal, tiene un sistema de transporte acuático bien desarrollado con rutas de barcos en la mayoría de las partes de Longzhou, convirtiéndolo en un centro de transporte desde la antigüedad. A medida que floreció el comercio, se convirtió naturalmente en el centro de la economía. Su capital, Haojin City, es extremadamente próspera y alberga a muchas familias adineradas de comerciantes, incluida la Lin Guild.",
  str_loading_h_desc128 = "Hace cientos de años, los restos de los Eclipsites enterrados en las aguas costeras del Reino Ji una vez corrompieron a los parientes de la Doncella Dragón, un dragón serpiente negro. La Doncella Dragón tuvo que dañarlo severamente, sellando la cueva marina para prevenir el desbordamiento del poder de los Eclipsites. Debido a la negligencia del reino sobre el gran ritual, el sello ha sido destruido, liberando a los Eclipsites para causar caos. El Reino Ji, aunque movilizó su fuerza para responder, ha experimentado pérdidas sustanciales.",
  str_loading_h_desc129 = "El Festival de Primavera es el festival más importante en el continente de Longzhou. La familia real organiza banquetes para invitados distinguidos mientras los ciudadanos se reúnen para el ocio y la socialización. En el Reino de Ji, los lugareños organizan ferias de templo, rinden homenaje a la Doncella Dragón y ahuyentan a la bestia Nian durante el festival, esperando salud y buena fortuna para el próximo año. Algunos comerciantes contratan a fiendlings para realizar espectáculos temáticos sobre el ritual de persecución de bestias, añadiendo un toque de diversión al comienzo del nuevo año.",
  str_loading_c_h_name205 = "Sala de Control de Aeronaves de la Federación Illumina",
  str_loading_c_h_name206 = "Frontera Nevada",
  str_loading_c_h_name207 = "Caverna Fronteriza",
  str_loading_c_h_name208 = "Altar ancestral",
  str_loading_c_h_name209 = "Murallas del Castillo",
  str_loading_e_h_name205 = "Frío e imponente, con un rico aroma a metal que perdura en el aire.",
  str_loading_e_h_name206 = "La raramente visitada frontera noroeste de Northland.",
  str_loading_e_h_name207 = "Una caverna antigua velada por capas de hielo.",
  str_loading_e_h_name208 = "El misterioso terreno sagrado custodiado por generaciones de la tribu Fox de la Nieve.",
  str_loading_e_h_name209 = "Un antiguo castillo devastado por la guerra.",
  str_loading_h_desc205 = "Aunque no es tan espacioso como la Sala de Control del Coloso, este lugar es suficiente para alojar a un equipo de expedición de tamaño medio. Sus paredes están cubiertas con paneles de instrumentos y pantallas intrincados, que registran con precisión varios parámetros y datos de la aeronave. A medida que los punteros en el panel de instrumentos oscilan constantemente, el tenue sonido mecánico rítmico parece resonar con la frecuencia de un cálculo mecánico gigante en lo profundo de una Ciudad Subterránea de Illumina.",
  str_loading_h_desc206 = "Bajo el sombrío cielo de nieve, el que una vez fue un desierto nevado sin límites parece tener un final. Altas montañas se alzan como un muro a lo lejos, dividiendo este lugar del mundo exterior. Sin embargo, el desolado Bosque Nevado enfrenta otro terrible asalto, con casas reducidas a escombros, pinos nevados cruelmente quebrados, y la nieve manchada con grandes parches de sangre rojo-negra... Parece que nadie sabe o se preocupa por las criaturas que viven aquí.",
  str_loading_h_desc207 = "La caverna helada presenta una estructura laberíntica y compleja. Algunas paredes de hielo se elevan verticalmente, mientras que otras son bajas y estrechas, obligando a los transeúntes a agacharse. La luz tenue se filtra a través de los cristales de hielo, proyectando sombras moteadas y cubriendo la cueva con una sombra serena y plateada. Las columnas de hielo altas y rugosas, junto con las flores de hielo en las paredes de la cueva, se transforman en formas peculiares, preparadas para el momento en que desciende la aurora.",
  str_loading_h_desc208 = "Dentro de las profundidades de la oscura caverna, haces de luz atraviesan el techo, proyectándose sobre el altar de abajo, como si los creadores del altar esperaran el despertar de los tres árboles sagrados. Ante el altar se encuentra una losa de piedra inscrita con antiguas runas, detallando la leyenda de los \"Tres Pinos\". Dos desgastadas estatuas de Nieve Fox hacen guardia, simbolizando la protección de su tribu sobre el altar. Los ancianos una vez dijeron que, a pesar de parecer congelada durante milenios, la bendición de los árboles sagrados perdura.",
  str_loading_h_desc209 = "Una ráfaga de viento se adentra en las profundidades de la cueva, soplando a través de un antiguo castillo imponente que emerge del suelo. En la furiosa ventisca, el interior del castillo brilla intensamente con fuego. Los defensores del castillo se mueven, sus espíritus elevados mientras avanzan para mantener su antiguo juramento. Sus gritos y el choque de las armas han desterrado el frío del hielo y la nieve, haciéndoles olvidar la dureza de esta era.",
  str_loading_N45_Cname_01 = "Base de Rediesel Wrench",
  str_loading_N45_Cname_02 = "Corredor de la línea Ley",
  str_loading_N45_Cname_03 = "Volcán Rugiente",
  str_loading_N45_Ename_01 = "Una base temporal establecida por Rediesel Wrench después de que dejaron de moverse. \nEficiente y conveniente.",
  str_loading_N45_Ename_02 = "Un camino sinuoso bajo el Desierto de Rediesel.\nEstos pasajes misteriosos están conectados a las líneas ley del desierto.",
  str_loading_N45_Ename_03 = "Un volcán subterráneo que siempre está rugiendo. Extrañamente, hizo erupción hace solo 15 años.",
  str_loading_N45_des_01 = "Debido al duro entorno del desierto, Rediesel Wrench a menudo se ve obligado a abandonar el oasis para buscar suministros.\nCuando Lepidoz se detiene, construirán una base temporal en el lugar.",
  str_loading_N45_des_02 = "Bajo el Desierto de Rediesel hay muchos pasajes sinuosos inexplicables que se extienden en todas direcciones y se llaman colectivamente el corredor de la línea ley.\nNadie sabe cómo se formaron, pero el corredor parece haber existido durante mucho tiempo e incluso se desarrolló por un tiempo. Sin embargo, todo fue destruido por el inicio de varios desastres.",
  str_loading_N45_des_03 = "El Rugiente Volcán es el volcán más peligroso en el Desierto de Rediesel. Usualmente está inactivo, pero siempre hace un rugido. La única vez que hizo erupción, destruyó la base original del Desierto de Rediesel.\nLos miembros de Rediesel Wrench temen a este volcán y no han regresado allí en muchos años.\nSegún algunos de los rumores que se propagan entre ellos, el rugido pertenece a los Eclipsitas que viven en el magma.",
  str_loading_N46_Cname_01 = "Colmillos Ocultos",
  str_loading_N46_Ename_01 = "Arcade Umbraton.\nEl símbolo de la comunidad de juegos de Astra.",
  str_loading_N46_des_01 = "Una sala de juegos fundada por jugadores experimentados. Comenzó como un pequeño club que servía a los Aurorianos que tenían debilidad por las consolas de juegos antiguas. A medida que se restauraban y desarrollaban más y más juegos, los jugadores de todo Astra se sintieron atraídos, y pronto la sala de juegos se convirtió en el principal punto de encuentro de la comunidad de jugadores.",
  str_loading_N47_Cname_01 = "Base: Nivel de Superficie",
  str_loading_N47_Cname_02 = "Base: Pasaje",
  str_loading_N47_Cname_03 = "Base: Abismo",
  str_loading_N47_Cname_04 = "Base: Ruinas",
  str_loading_N47_Cname_05 = "Punta de lanza",
  str_loading_N47_Ename_01 = "El Tiempo y la Fundación Caen Juntos",
  str_loading_N47_Ename_02 = "Eco del Espacio del Instrumento Abandonado",
  str_loading_N47_Ename_03 = "El Punto de ruptura de los recuerdos y el Punto de inflexión de la vida",
  str_loading_N47_Ename_04 = "Lugar de Descanso de la Punta de Lanza del Colossus Hecho Trizas",
  str_loading_N47_Ename_05 = "Donde los fantasmas del pasado persisten",
  str_loading_N47_des_01 = "Una base experimental enterrada por Illumina. Podría haber permanecido oculta si no hubiera sido por la inmensa fuerza de Barton que creó una apertura.\nLa frágil fundación forma un fuerte contraste con las sólidas murallas de la ciudad de Illumina de hoy. Sin embargo, los secretos del pasado siempre aguardan su tiempo, esperando a la persona adecuada para descubrirlos.\nEste lugar ha sido testigo tanto de entrenamientos apasionados como de crueles experimentos, así como de luchas desesperadas y rebeldías ardientes.",
  str_loading_N47_des_02 = "Los instrumentos descartados actúan como guardias que obstruyen el camino de los intrusos. Varios instrumentos aún funcionales asomaron desde las ruinas, interrumpiendo los pensamientos de los intrusos mientras secretamente hacían planes. Esta es una cueva oscura que aísla los gritos angustiados, y un largo túnel que pone a prueba a los soñadores. Si escuchas una voz que te llama, tal vez deberías detenerte y ver si es tu pasado abandonado que te está alcanzando.",
  str_loading_N47_des_03 = "Esa fue una época de insoportable dificultad, enterrando innumerables experiencias de vida abandonadas. Encima del abismo está el terreno alto de los vencedores, y debajo de él está el cementerio de los sacrificados. Cualquiera que desee derrocar este injusto pasado debe sumergirse en el abismo. Solo cuando sus cuerpos están ardiendo y no queda carne para ser destruida pueden volar para siempre.",
  str_loading_N47_des_04 = "En el fondo mismo de la base experimental yace un Coloso con una cola rota que todavía tiene una conciencia débil.Su voluntad tenaz parece estar ordenando a sus partes dispersas que se unan mientras espera el comando de un Navegador para partir hacia su antiguo hogar. Parece haber estado aquí más tiempo que toda la historia de Illumina, y la verdad de este experimento es revelada por todo el equipo experimental construido a su alrededor en un momento posterior.",
  str_loading_N47_des_05 = "Esta peligrosa transacción es la última pista disponible para todos los exploradores. \nA través de un instrumento especial, uno puede ver los datos restantes de la sala de control principal de Spearhead. Aunque la sala está en ruinas, su estructura interna es más concisa y suave en comparación con Soroz, y cada panel de control exuda un aura peligrosa. ¿Vino de la Zona Oscura? ¿Podría su Navegante ser un Caelestite?",
  str_loading_N48_Cname_01 = "Ciudad de Varaki",
  str_loading_N48_Cname_02 = "Advenimiento de la Verdad",
  str_loading_N48_Cname_03 = "Tumba de Varaki",
  str_loading_N48_Cname_04 = "El castillo de Wilhelm",
  str_loading_N48_Cname_05 = "Templo de la Verdad",
  str_loading_N48_Ename_01 = "Patria de la familia de vampiros.",
  str_loading_N48_Ename_02 = "Gran asamblea de la Orden Verdadera.",
  str_loading_N48_Ename_03 = "Lugar de descanso de los antepasados de Varaki.",
  str_loading_N48_Ename_04 = "Un castillo frío y solitario en el acantilado.",
  str_loading_N48_Ename_05 = "Un salón carmesí sagrado y espeluznante.",
  str_loading_N48_des_01 = "la familia de vampiros, una raza Auroriana distinta, ha habitado durante mucho tiempo la ciudad de Varaki, según dicen las leyendas. Prefieren la noche y tienen un ansia de sangre. Sus vidas se prolongan, a menudo manteniendo la apariencia que tenían al despertar su linaje.\nLos descendientes de esta familia heredan el gran poder de sus antepasados cuando se despierta su linaje. Sin embargo, los dolorosos recuerdos que vienen con este poder son el costo que deben soportar.",
  str_loading_N48_des_02 = "Cada tres años, ocurre una noche así: a medianoche, las campanas del Templo de la Verdad suenan, y los altos campanarios se extienden y alcanzan la luna.La luna, brillando en rojo sangre, se asienta en el cielo como si el Señor de la Verdad estuviera escuchando sus confesiones en el templo y compartiendo la gloria y los secretos de la familia. Los discípulos de la Verdad visten túnicas y marchan con ataúdes por las calles, cantando reverentemente el nombre del Señor, esperando la llegada del Señor de la Verdad.",
  str_loading_N48_des_03 = "El clan Varaki considera los restos de sus antepasados como tesoros y, en momentos específicos, los observa con el líder de la familia y los discípulos. Además, los antiguos ataúdes en las tumbas guardan muchos secretos ocultos.\nPlantas negras con un resplandor místico rodean las tumbas, que, bajo la luz de la luna sangrienta, tomarán la forma semi-humana y abrirán las puertas de la tumba para los elegidos.",
  str_loading_N48_des_04 = "En la vasta y fría casa antigua, un gran ataúd descansa en el centro del salón, donde las flores nunca se marchitan y las velas nunca se apagan, como si fueran los únicos compañeros del dueño del ataúd. \nTodos llaman al ataúd la cama de hielo de un vampiro. Sin embargo, nadie sabe que alguien una vez dejó atrás el ruido del pueblo y vino aquí, con un alma hirviendo como agua caliente, leyendo, meditando y buscando el camino a la Verdad solo.",
  str_loading_N48_des_05 = "Es el lugar donde los discípulos de True Order confiesan y aprenden. En la noche del Advenimiento de la Verdad, los líderes de la Orden y los jefes de familia dirigen conjuntamente una importante ceremonia de \"escucha\".\nSe les dice a los discípulos que deben revelar sus cuerpos débiles y yacer en el ataúd con corazones piadosos. Luego, durante el canto del jefe de la familia, los antepasados de Varaki, e incluso el Señor de la Verdad, descenderán sobre este discípulo, hablando revelación a través de su boca.",
  str_loading_c_h_name_laisha1 = "La Isla Solitaria",
  str_loading_e_h_name_laisha1 = "Tierra de las Ruinas Antiguas",
  str_loading_h_desc_laisha1 = "En los mares distantes, yace una isla solitaria olvidada por el mundo, rodeada de un azur interminable y cubierta de una vegetación densa y exuberante. Antiguas ruinas descansan dentro de esta cuna verde prístina, habiendo resistido a través de las edades.",
  str_loading_c_h_name_laisha2 = "Aventura de verano",
  str_loading_e_h_name_laisha2 = "Compañeros, Juntos",
  str_loading_h_desc_laisha2 = "La isla yace silenciosamente en el fondo del mar, junto con las evidencias de su antigua gloria. Ahora, está a punto de comenzar una nueva aventura de verano.\nLos compañeros que están a tu lado son los tesoros más preciados.\n¡En el tiempo limitado que tienes, disfruta de esta aventura interminable con tus compañeros!",
  str_loading_c_h_name_N5001 = "Puerto de Harbor City",
  str_loading_c_h_name_N5002 = "Acuario",
  str_loading_c_h_name_N5003 = "Fantasía de Acuario",
  str_loading_e_h_name_N5001 = "La brisa marina sopla suavemente, y las aves migratorias siguen cantando.",
  str_loading_e_h_name_N5002 = "El mar en tierra, un mundo tranquilo.",
  str_loading_e_h_name_N5003 = "El océano en el sueño, un mundo reconocido de nuevo.",
  str_loading_h_desc_N5001 = "Harbor City, un lugar raro de tranquilidad en Astra.\nSin embargo, una sensación de calma a menudo precede al trastorno.\nA pesar de las tormentas inevitables, la ciudad, como las olas perdurables, siempre se recupera.",
  str_loading_h_desc_N5002 = "Los peces vinieron del mar pero al final se establecieron juntos en tierra.\nCon el sonido de la concha, caen en un sueño pacífico.\nY esta escena armoniosa se convierte en un país de maravillas para los visitantes.",
  str_loading_h_desc_N5003 = "¿Alguna vez has soñado? En los sueños, lo ordinario se transforma en lo extraño. Como un cuarto trasero sombrío y brillante, hay una extraña familiaridad con lo desconocido. Es en estos reinos crepusculares de la mente donde redescubrimos el mundo que pensábamos que conocíamos.",
  str_loading_21001_name = "Tierras de la Zona Oscura",
  str_loading_21001_name_title = "Medio Paso de la Noche Eterna",
  str_loading_21001_desc = "Para los Aurorianos, entrar en la Zona Oscura es como renunciar a la vida misma.\nNo hay Lumina que los apoye aquí, solo sombras que lo ahogan todo.\nPero para el Eclipse, es un terreno de caza ideal.\nAun así, incluso así, los intrépidos avanzan a través de la niebla, decididos a descubrir los secretos dentro.",
  str_loading_21002_name = "Sector Inexplorado 44",
  str_loading_21002_name_title = "Terrenos de coral",
  str_loading_21002_desc = "Una tierra sin vida invadida por el coral.\nEl tiempo parece congelado aquí, y la luz lo ha abandonado.\nAlgunos rastros de vida aún se pueden encontrar en sus fronteras.\nPero para aquellos que aún deambulan aquí, no importa.\nEste es un lugar maldito para repeler la luz, condenando a todos los seres vivos."
}
return config
